/**
 * exportPdf.js - Dashboard download as a PDF (T021, FR-2.4).
 *
 * A4 landscape, built in the browser from the export model
 * (utils/dashboardExport.js), so it holds exactly the rows on screen.
 *   - Header: title, view, when and by whom, filters, sort, row count, and
 *     the Business Unit status counts.
 *   - Table: the Dashboard's columns for the current view. The Status cells
 *     draw a coloured square next to the status in words ("Pending"), so
 *     the PDF reads the same printed in black and white.
 *   - Footer on every page: "Page n of N" and the "never generated by AI"
 *     line.
 * Every field is kept in the Excel download; the PDF keeps the columns that
 * fit a landscape page.
 *
 * jsPDF's built-in Helvetica only covers Western European characters; any
 * other character is written as "?" rather than as garbled text (see
 * pdfSafe). jsPDF and jspdf-autotable load only when someone downloads.
 */
import { AI_NOTE, formatDay, formatGeneratedAt, rowCountLabel } from './dashboardExport';

const NAVY = [15, 23, 42];
const TEXT_2 = [71, 85, 105];
const BORDER = [203, 213, 225];
const MUTED_FILL = [241, 245, 249];
const STATUS_RGB = { compliant: [34, 197, 94], pending: [245, 158, 11], action_needed: [239, 68, 68] };
const NOT_SET_RGB = [100, 116, 139];

const MARGIN = 10; // mm
const FONT = 8; // pt, table body
const SQUARE = 2.6; // mm, status mark
const STATUS_PAD_LEFT = 2 + SQUARE + 1.6;

// Characters Helvetica (WinAnsiEncoding) can draw beyond Latin-1.
const WIN_ANSI_EXTRA = new Set('€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ');
const REPLACEMENTS = { '→': '->', '←': '<-', '≤': '<=', '≥': '>=', '≠': '!=', '✓': 'v', ' ': ' ' };

/** Keeps text Helvetica can draw; anything else becomes "?". */
export function pdfSafe(value) {
  let out = '';
  for (const ch of String(value ?? '')) {
    if (REPLACEMENTS[ch]) out += REPLACEMENTS[ch];
    else if (ch === '\n' || ch === '\t') out += ch;
    else {
      const code = ch.codePointAt(0);
      out += (code >= 0x20 && code <= 0x7e) || (code >= 0xa0 && code <= 0xff) || WIN_ANSI_EXTRA.has(ch) ? ch : '?';
    }
  }
  return out;
}

const DASH = '-';

function orDash(value) {
  return value ? pdfSafe(value) : DASH;
}

function regulationText(row) {
  const parts = [row.name];
  if (row.name !== row.title) parts.push(row.title);
  parts.push(`ID ${row.id}`);
  return pdfSafe(parts.join('\n'));
}

function columnsFor(model) {
  // Widths add up to the 277 mm between the margins of A4 landscape.
  if (model.view === 'bu') {
    return [
      { key: 'regulation', header: 'Regulation', width: 44, value: regulationText },
      { key: 'unit', header: 'Business unit', width: 26, value: (r) => pdfSafe(r.unit) },
      { key: 'status', header: 'Status', width: 30, status: (r) => [{ cell: r.status }] },
      { key: 'explanation', header: 'Explanation', width: 52, value: (r) => orDash(r.status.note) },
      { key: 'due', header: 'Due date', width: 23, value: (r) => formatDay(r.dueDate) || DASH },
      { key: 'domain', header: 'Domain', width: 21, value: (r) => orDash(r.domain) },
      { key: 'country', header: 'Country', width: 16, value: (r) => orDash(r.country) },
      { key: 'region', header: 'Region', width: 18, value: (r) => orDash(r.region) },
      { key: 'notes', header: 'Notes', width: 37, value: (r) => orDash(r.notes) },
      { key: 'docs', header: 'Docs', width: 12, value: (r) => String(r.documents.length), align: 'center' },
    ];
  }
  return [
    { key: 'regulation', header: 'Regulation', width: 46, value: regulationText },
    { key: 'due', header: 'Due date', width: 23, value: (r) => formatDay(r.dueDate) || DASH },
    { key: 'domain', header: 'Domain', width: 23, value: (r) => orDash(r.domain) },
    { key: 'country', header: 'Country', width: 16, value: (r) => orDash(r.country) },
    { key: 'region', header: 'Region', width: 18, value: (r) => orDash(r.region) },
    {
      key: 'status',
      header: 'Status by Business Unit',
      width: 68,
      status: (r) => r.unitStatuses.map((u) => ({ cell: u.cell, prefix: `${u.unit}: ` })),
    },
    { key: 'notes', header: 'Notes', width: 47, value: (r) => orDash(r.notes) },
    { key: 'docs', header: 'Docs', width: 12, value: (r) => String(r.documents.length), align: 'center' },
    { key: 'updated', header: 'Last updated', width: 22, value: (r) => formatDay(r.lastUpdated) || DASH },
  ];
}

function statusLine(item) {
  const { cell, prefix = '' } = item;
  return pdfSafe(`${prefix}${cell.label}${cell.note && prefix ? ` - ${cell.note}` : ''}`);
}

function drawSquare(doc, x, y, status) {
  if (status) {
    doc.setFillColor(...STATUS_RGB[status]);
    doc.setDrawColor(...NAVY);
    doc.setLineWidth(0.15);
    doc.rect(x, y, SQUARE, SQUARE, 'FD');
  } else {
    doc.setDrawColor(...NOT_SET_RGB);
    doc.setLineWidth(0.3);
    doc.setLineDashPattern([0.5, 0.4], 0);
    doc.rect(x, y, SQUARE, SQUARE, 'S');
    doc.setLineDashPattern([], 0);
  }
}

/** Header block on page 1; returns the y where the table starts. */
function drawHeader(doc, model) {
  const pageW = doc.internal.pageSize.getWidth();
  doc.setFillColor(...NAVY);
  doc.rect(0, 0, pageW, 16, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(13);
  doc.text(`Regulator - ${model.title}`, MARGIN, 10.5);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.text(pdfSafe(model.viewLabel), pageW - MARGIN, 10.5, { align: 'right' });

  let y = 23;
  const rows = [
    ['Generated', pdfSafe(`${formatGeneratedAt(model.generatedAt)}${model.generatedBy ? ` by ${model.generatedBy}` : ''}`)],
    ['Filters', pdfSafe(model.filterLines.length ? model.filterLines.join('; ') : 'None')],
    ['Sorted by', pdfSafe(model.sortLabel)],
    ['Rows', rowCountLabel(model)],
  ];
  doc.setFontSize(8.5);
  for (const [label, value] of rows) {
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...NAVY);
    doc.text(label, MARGIN, y);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...TEXT_2);
    const wrapped = doc.splitTextToSize(value, pageW - MARGIN * 2 - 24);
    doc.text(wrapped, MARGIN + 24, y);
    y += wrapped.length * 4;
  }

  // Status counts, each with its mark.
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...NAVY);
  doc.text('Unit statuses', MARGIN, y);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(...TEXT_2);
  let x = MARGIN + 24;
  const items = [
    ['action_needed', 'Action needed', model.counts.action_needed],
    ['pending', 'Pending', model.counts.pending],
    ['compliant', 'Compliant', model.counts.compliant],
    [null, 'Not set', model.counts.none],
  ];
  for (const [status, label, n] of items) {
    drawSquare(doc, x, y - SQUARE + 0.3, status);
    const textValue = `${label} ${n}`;
    doc.text(textValue, x + SQUARE + 1.4, y);
    x += SQUARE + 1.4 + doc.getTextWidth(textValue) + 6;
  }
  return y + 5;
}

function drawFooter(doc, model, pageNumber, totalPagesExp) {
  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();
  doc.setDrawColor(...BORDER);
  doc.setLineWidth(0.2);
  doc.line(MARGIN, pageH - 9, pageW - MARGIN, pageH - 9);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...TEXT_2);
  doc.text(pdfSafe(`Regulator - ${model.title} - ${formatGeneratedAt(model.generatedAt)}. ${AI_NOTE}`), MARGIN, pageH - 5);
  // Left-aligned at a fixed spot: the page total is filled in after the
  // table is drawn, so its width isn't known yet.
  doc.text(`Page ${pageNumber} of ${totalPagesExp}`, pageW - MARGIN - 20, pageH - 5);
}

/** Returns the PDF as a Blob. */
export async function buildDashboardPdf(model) {
  const [{ jsPDF }, { autoTable }] = await Promise.all([import('jspdf'), import('jspdf-autotable')]);
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  doc.setProperties({ title: `Regulator - ${model.title}`, subject: model.viewLabel, creator: 'Sustainer Regulator' });

  const columns = columnsFor(model);
  const statusIndex = columns.findIndex((c) => c.status);
  const startY = drawHeader(doc, model);
  const totalPagesExp = '{total_pages_count_string}';

  // Status cells: text drawn by autotable after a left gutter; the coloured
  // squares go in the gutter, one per unit, level with that unit's first line.
  const statusLayout = new Map(); // row index -> [{ status, line }]

  const body = model.rows.map((row) =>
    columns.map((col) => (col.status ? '' : col.value(row)))
  );

  autoTable(doc, {
    head: [columns.map((c) => c.header)],
    body,
    startY,
    margin: { left: MARGIN, right: MARGIN, top: 12, bottom: 13 },
    theme: 'grid',
    styles: {
      font: 'helvetica',
      fontSize: FONT,
      textColor: NAVY,
      lineColor: BORDER,
      lineWidth: 0.15,
      cellPadding: { top: 1.6, right: 2, bottom: 1.6, left: 2 },
      valign: 'top',
      overflow: 'linebreak',
    },
    headStyles: { fillColor: NAVY, textColor: [255, 255, 255], fontStyle: 'bold', valign: 'middle' },
    alternateRowStyles: { fillColor: MUTED_FILL },
    columnStyles: Object.fromEntries(
      columns.map((c, i) => [
        i,
        {
          cellWidth: c.width,
          halign: c.align || 'left',
          ...(c.status ? { cellPadding: { top: 1.6, right: 2, bottom: 1.6, left: STATUS_PAD_LEFT } } : {}),
        },
      ])
    ),
    didParseCell: (data) => {
      if (data.section !== 'body' || data.column.index !== statusIndex) return;
      const items = columns[statusIndex].status(model.rows[data.row.index]);
      doc.setFontSize(FONT);
      const width = columns[statusIndex].width - STATUS_PAD_LEFT - 2;
      const lines = [];
      const layout = [];
      if (!items.length) lines.push(DASH);
      for (const item of items) {
        layout.push({ status: item.cell.status, line: lines.length });
        lines.push(...doc.splitTextToSize(statusLine(item), width));
      }
      data.cell.text = lines;
      statusLayout.set(data.row.index, layout);
    },
    didDrawCell: (data) => {
      if (data.section !== 'body' || data.column.index !== statusIndex) return;
      const layout = statusLayout.get(data.row.index) || [];
      const k = doc.internal.scaleFactor;
      const fontMm = FONT / k;
      const lineMm = fontMm * doc.getLineHeightFactor();
      const firstBaseline = data.cell.y + data.cell.padding('top') + fontMm * (2 - 1.15);
      for (const { status, line } of layout) {
        const baseline = firstBaseline + line * lineMm;
        drawSquare(doc, data.cell.x + 2, baseline - SQUARE + 0.2, status);
      }
    },
    didDrawPage: (data) => drawFooter(doc, model, data.pageNumber, totalPagesExp),
  });

  if (typeof doc.putTotalPages === 'function') doc.putTotalPages(totalPagesExp);
  return doc.output('blob');
}
